<?php
declare(strict_types=1);if(PHP_SAPI!=='cli')exit(404);require_once dirname(__DIR__).'/config.php';$root=dirname(__DIR__);$now=time();$deleted=0;$compressed=0;foreach(glob($root.'/logs/*')?:[] as$f){if(!is_file($f)||basename($f)==='.htaccess')continue;$age=$now-(int)filemtime($f);if($age>30*86400){@unlink($f);$deleted++;}elseif($age>7*86400&&!str_ends_with($f,'.gz')&&function_exists('gzencode')){$raw=@file_get_contents($f);if(is_string($raw)&&@file_put_contents($f.'.gz',gzencode($raw,6),LOCK_EX)!==false){@unlink($f);$compressed++;}}}foreach([sys_get_temp_dir().'/redfox_login_limits/*',sys_get_temp_dir().'/rx_reseller_api_*',sys_get_temp_dir().'/redfox_log_dedup/*']as$g)foreach(glob($g)?:[]as$f)if(is_file($f)&&$now-filemtime($f)>86400)@unlink($f);try{$pdo->prepare('DELETE FROM reseller_message_queue WHERE status IN (\'sent\',\'failed\',\'cancelled\') AND sent_at IS NOT NULL AND sent_at<?')->execute([$now-90*86400]);$pdo->prepare('DELETE FROM reseller_api_keys WHERE revoked_at IS NOT NULL AND revoked_at<?')->execute([$now-180*86400]);$pdo->prepare('DELETE FROM reseller_api_nonces WHERE used_at<?')->execute([$now-86400]);$pdo->prepare('DELETE FROM reseller_api_idempotency WHERE created_at<?')->execute([$now-90*86400]);$pdo->prepare('DELETE FROM reseller_recovery_codes WHERE used_at IS NOT NULL AND used_at<?')->execute([$now-180*86400]);}catch(Throwable$e){fwrite(STDERR,redfox_exception_fingerprint($e)."\n");}echo"compressed=$compressed deleted=$deleted\n";
